 function paperFooter(){
  const data=ensurePaper(),fresh=data.pages[data.active].blocks.some(b=>b.text.trim()&&b.text!==b.submittedText);
  if(clearPaperConfirm)return html`<div class="dn-paper-footer dn-clear-confirm"><small>ล้างเฉพาะกระดาษ ผลในเรื่องยังอยู่</small>${button('paper-clear',t('ล้างกระดาษ'))}${button('paper-keep',t('เก็บไว้'))}</div>`;
  return `<div class="dn-writing-footer"><div class="dn-paper-footer"><div>${button('paper-clear-open',t('ล้างทั้งหมด'),'dn-paper-small',working?'disabled':'')}</div><div class="dn-paper-folios">${button('paper-prev','⟵','','aria-label="'+t('หน้าก่อน')+'" '+(data.active===0||working?'disabled':''))}<span>${String(data.active+1).padStart(2,'0')}</span>${button('paper-next','⟶','','aria-label="'+t('หน้าถัดไป')+'" '+(working?'disabled':''))}</div>${button('paper-inscribe',working?t('กำลังเขียน…'):t('ต่อเรื่อง'),'dn-paper-submit',!fresh||working?'disabled':'')}</div><small class="dn-paper-status" role="status">${esc(notice)}</small></div>`;
 }
 function paperError(error){notice=t(error?.message||error);for(const node of [root,panel]){const status=node.querySelector('.dn-paper-status');if(status)status.textContent=notice;}}
 function queuePaper(next){
  ensurePaper();paperState=cleanPaper(next);paperDirty=true;clearTimeout(paperTimer);const captured=scope();paperTimer=setTimeout(()=>{if(scope()===captured)void savePaper().catch(paperError);},350);
  for(const node of [root,panel]){const save=node.querySelector('[data-dn-action=paper-inscribe]');if(save)save.disabled=working||!paperState.pages[paperState.active].blocks.some(b=>b.text.trim()&&b.text!==b.submittedText);}
 }
 function savePaper(){
  clearTimeout(paperTimer);if(!paperDirty)return paperQueue;const captured=scope(),snapshot=cleanPaper(paperState),id=bookId||currentBook()?.id,message=chat().findLast(m=>!m.is_user&&!m.is_system),context=c(),sourceTurn=replyAnchor(chat());
  if(!id||!message||message.is_user||message.is_system)return Promise.reject(Error(t('รอคำตอบ AI ก่อน')));
  const task=paperQueue.catch(()=>{}).then(async()=>{if(scope()!==captured||!enabled())throw Error(t('เปลี่ยนแชทแล้ว'));const previous=message.extra?.[PAPER];message.extra||={};message.extra[PAPER]=paperRows(message,id,snapshot,{sourceTurn});
   try{await context.saveChat();if(scope()!==captured)throw Error(t('เปลี่ยนแชทระหว่างบันทึก'));if(JSON.stringify(paperState)===JSON.stringify(snapshot))paperDirty=false;}catch(error){if(scope()===captured){if(previous)message.extra[PAPER]=previous;else delete message.extra[PAPER];}throw error;}
  });paperQueue=task;return task;
 }
 async function prepareGeneration(type='normal'){
  if(disposed||!enabled()||!scope()||working||!['','normal','continue'].includes(type))return;
  const captured=scope();if(bootstrap)await bootstrap;await api.prepareNpcs?.();if(scope()!==captured||!enabled())return;
  await savePaper();if(scope()!==captured||!enabled())throw Error(t('เปลี่ยนแชทแล้ว'));
  const context=c(),message=chat().findLast(m=>!m.is_user&&!m.is_system);if(!message)return;
  const sourceTurn=replyAnchor(chat()),current=state(),w=world(),previous=message.extra?structuredClone(message.extra):{},papers=[];const requests=[],errors=[];
  for(const b of writingMaterials(w)){
   if(!canWrite(w,current,b.id))continue;
   const paper=b.id===currentBook()?.id?ensurePaper():readPaper(chat(),b.id),stage=stageWrittenPaper(paper,current,w,[...records(),...requests.map(r=>({...r,status:'waiting'}))],b.id);
   errors.push(...stage.errors);if(stage.requests.length||(JSON.stringify(stage.paper)!==JSON.stringify(paper))){papers.push({bookId:b.id,paper:stage.paper});requests.push(...stage.requests);}
  }
  if(papers.length){
   if((message.extra?.[INSCRIPTIONS]?.length||0)+requests.length>128)throw Error(t('หน้านี้เต็มแล้ว เริ่มเทิร์นเรื่องใหม่ก่อนจดเพิ่ม'));
   message.extra||={};message.extra[INSCRIPTIONS]=[...(message.extra[INSCRIPTIONS]||[]),...requests.map(r=>({...r,...(sourceTurn?{sourceTurn}:{}),swipe:Number(message.swipe_id)||0,offset:visibleText(message.mes).length}))];
   for(const p of papers)message.extra[PAPER]=paperRows(message,p.bookId,p.paper,{sourceTurn});
   try{await context.saveChat();if(scope()!==captured||!enabled())throw Error(t('เปลี่ยนแชทระหว่างบันทึก'));}
   catch(error){message.extra=previous;throw error;}
   const active=papers.find(p=>p.bookId===currentBook()?.id);if(active){paperState=active.paper;paperDirty=false;}
  }
  notice=errors.length?t(errors[0]):requests.length?t('จดชื่อแล้ว รอผลในเนื้อเรื่อง'):notice;
  refresh();if(papers.length||errors.length){render();renderDock();}return requests;
 }
 function attachPaperEditors(){
  if(root.open&&page==='write'&&access())paperEditor=mountPaperEditor({host:root.querySelector('[data-dn-paper]'),paper:ensurePaper(),onChange:queuePaper,onError:paperError,disabled:working||busy()});
 }
 async function inscribePaper(){
  if(working||busy()||!access())return;working=true;const captured=scope();let proposals,queued=[];
  try{await api.prepareNpcs?.();proposals=paperInputs(ensurePaper(),state(),world());for(const p of proposals){if(!p.input.cause)p.input.cause=t('หัวใจวาย');const check=eligibleTarget(state(),p.input);if(!check.ok)throw Error(check.message);}render();renderDock();await savePaper();}
  catch(error){working=false;notice=t(error.message);render();renderDock();return;}
  notice='';render();renderDock();
  try{const result=await continueInscriptions({context:c(),scope,currentState:state,inputs:proposals.map(p=>({...p.input,bookId:currentBook()?.id})),enabled,hasAccess:access,commitResult,onQueued:requests=>{queued=requests;}});if(scope()!==captured)return;paperState=markPaperSubmitted(paperState,proposals.flatMap(p=>p.blockIds));paperDirty=true;await savePaper();notice=result.warning?t(result.warning):t('เรื่องราวบันทึกผลแล้ว');}
  catch(error){if(scope()===captured){if(queued.some(r=>records().some(e=>e.id===r.id))){paperState=markPaperSubmitted(paperState,proposals.flatMap(p=>p.blockIds));paperDirty=true;await savePaper().catch(()=>{});}notice=t(error.message);}}
  finally{working=false;if(scope()===captured){refresh();render();renderDock();}}
 }
 function reviewPage(){return html`<div class="dn-paper-heading"><span>ก่อนที่หมึกจะลงบนกระดาษ</span><span>確認</span></div><div class="dn-inscription-preview"><h2>${esc(draft.name)}</h2><p>${esc(draft.cause||t('หัวใจวาย'))}</p><p>${esc(draft.details||'')}</p><small>${draft.timing==='default'?t('40 วินาทีในเรื่อง'):draft.delaySeconds/60+t(' นาทีในเรื่อง')}</small></div><p class="dn-warning-ink">ชื่อที่บอกคุณอาจไม่ใช่ชื่อจริง สมุดจะไม่เฉลยว่าชื่อนั้นถูกหรือผิดก่อนเขียน</p><div class="dn-paper-sign">${button('inscribe',working?t('กำลังเขียน…'):t('จดชื่อนี้ ')+fa('signature'),'dn-ink-action',working?'disabled':'')}${button('edit',t('ยกปากกากลับ'),'dn-pencil-link')}</div>`;}
 function recordsPage(){const entries=records(),w=world(),current=state();let unsubmitted=[];const b=currentBook();if(b&&access())try{unsubmitted=paperInputs(ensurePaper(),current,w,{optional:true}).filter(p=>!eligibleTarget(current,p.input).ok).map(p=>({name:p.input.name,message:t(eligibleTarget(current,p.input).message)}));}catch(error){unsubmitted=[{name:t('หมึกที่ยังไม่ส่ง'),message:t(error.message)}];}
  return html`<div class="dn-paper-heading"><span>名前 / WRITTEN NAMES</span><span>${entries.length} รายชื่อ</span></div><h2 class="dn-hand-heading">หมึกที่เขียนลงไปแล้ว</h2><div class="dn-journal">${unsubmitted.map(e=>`<article class="dn-unsubmitted"><div><h3>${esc(e.name)}</h3><span class="dn-entry-status">${t('ยังไม่ส่ง')}</span></div><p>${esc(e.message)}</p><small>${t('แก้หมึกบนกระดาษแล้วต่อเรื่องได้')}</small></article>`).join('')}${entries.toReversed().map(e=>{const progress=inscriptionProgress(e,current,uiLanguage());return `<article data-dn-entry="${esc(e.id)}" data-dn-progress="${progress.code}"><div><h3>${esc(e.name)}</h3><span class="dn-entry-status ${e.status}">${esc(progress.label)}</span></div><small class="dn-journal-book">${esc(w.fragments?.[e.bookId]?t('เศษกระดาษ')+' · '+w.fragments[e.bookId].parentBookId:e.bookId||t('บันทึกเก่า · ไม่ระบุเล่ม'))}</small><p>${esc(e.cause)}</p>${e.details&&e.details!==e.cause?'<p>'+esc(e.details)+'</p>':''}<div class="dn-progress-line"><span style="width:${Math.round(progress.fraction*100)}%"></span></div><p class="dn-progress-detail">${esc(progress.detail)}</p><small>${e.writtenTimeEstimated?t('กู้คืนจากข้อความในเรื่อง · ไม่ได้บันทึกเวลาจดไว้'):paperTime(e.writtenStorySeconds)+' → '+paperTime(e.dueStorySeconds)}</small>${e.evidence?`<details class="dn-outcome-evidence"><summary>${t('หลักฐานในเรื่อง')}</summary><p>${esc(e.evidence)}</p></details>`:''}</article>`;}).join('')||t('<p class="dn-blank-note">ยังไม่มีชื่อบนหน้ากระดาษ</p>')}</div>${button('new',t('พลิกไปหน้าว่าง ')+fa('arrow-right'),'dn-pencil-link')}`;}
 function lockedPage(){const b=currentBook();return html`<div class="dn-paper-heading"><span>สมุดที่ยังเอื้อมไม่ถึง</span><span>所有</span></div><div class="dn-empty-page">${fa('book')}<h2>${b?.holderId&&b.holderId!=='player'?t('สมุดอยู่กับ ')+esc(label(b.holderId)):t('คุณยังไม่ได้ถือสมุด')}</h2><p>${b?.ownerId==='player'?t('สิทธิ์ยังเป็นของคุณ แต่ต้องได้รับสมุดคืนก่อนจึงจะเขียนได้'):t('ติดตั้ง Addon แล้วไม่ได้รับสมุด ต้องพบและหยิบมันในเนื้อเรื่องก่อน')}</p>${b&&!b.holderId?button('rights',t('ดูสมุดที่พบ'),'dn-pencil-link'):''}</div>`;}
 function actorList(){return (state().npcs||[]).filter(n=>n.met===true&&n.enabled!==false&&n.inScene!==false&&n.stats?.hp!==0).map(n=>`<button type="button" data-dn-lend-target="${esc(n.id)}" aria-pressed="${actionTarget===n.id}"><span>${eyeLabel(n)}</span><small>${esc(n.title||n.occupation||t('ในฉาก'))}</small></button>`).join('');}
 function rightsPage(){const b=currentBook(),w=world();if(!b)return lockedPage();if(b.parentBookId)return fragmentRightsPage(b);const touch=b.touchedBy.includes('player');return html`<div class="dn-paper-heading"><span>このノート / POSSESSION</span><span>สิทธิ์ในสมุด</span></div><h2 class="dn-hand-heading">สมุดอยู่กับใคร</h2><dl class="dn-ownership"><div><dt>ผู้ถือสมุดในตอนนี้</dt><dd>${esc(label(b.holderId))}${!b.holderId?'<small>'+esc(b.location||t('ในฉาก'))+'</small>':''}</dd></div><div><dt>เจ้าของสิทธิ์</dt><dd>${b.ownerKnownToPlayer?esc(label(b.ownerId)):t('ยังไม่ทราบ')}</dd></div><div><dt>เจ้าของมนุษย์คนแรก</dt><dd>${esc(label(b.firstHumanOwnerId))}</dd></div><div><dt>ยมทูตเจ้าของเดิม</dt><dd>${touch&&b.originalShinigamiId?esc(label(b.originalShinigamiId)):t(touch?'ยังไม่ทราบยมทูตประจำสมุด':'ยังมองไม่เห็น')}</dd></div><div><dt>${t('ยมทูตเจ้าของปัจจุบัน')}</dt><dd>${touch&&b.currentShinigamiId?esc(label(b.currentShinigamiId)):t('ยังมองไม่เห็น')}</dd></div><div><dt>${t('ยมทูตประจำสมุด')}</dt><dd>${touch&&b.attachedShinigamiId?esc(label(b.attachedShinigamiId)):t('ยังมองไม่เห็น')}</dd></div></dl>${w.memoryLost?t('<p class="dn-warning-ink">สละสิทธิ์ในสมุดเล่มสุดท้ายแล้ว ความทรงจำเกี่ยวกับ Death Note และดวงตาจากข้อตกลงหายไป ดวงตาที่มีโดยไม่แลกยังอยู่ อายุขัยที่จ่ายไปไม่คืนกลับ</p>'):''}${!b.holderId?html`<p class="dn-margin-note">พบสมุดปกดำที่ ${esc(b.location)} จะทำอย่างไร</p><div class="dn-found-actions">${button('touch',t('แตะปก'))}${button('take',t('หยิบสมุด'))}${button('leave',t('ปล่อยไว้'))}</div>`:''}${access()?`<div class="dn-rights-options">${button('lend-open',t('ส่งสมุดให้ยืม ')+fa('arrow-right'),'dn-pencil-link')}${button('drop-open',t('วาง / ทิ้งสมุดไว้'),'dn-pencil-link')}${button('write',t('เปิดหน้าจดชื่อ'),'dn-pencil-link')}</div>`:''}${b.ownerId==='player'&&b.holderId&&b.holderId!=='player'?button('request-return',t('ขอรับสมุดคืน'),'dn-pencil-link'):''}${b.ownerId==='player'?`<div class="dn-rights-options">${button('deal',t('ข้อแลกเปลี่ยนกับยมทูต'),'dn-pencil-link',!touch||!shinigami(b)||w.eyes?'disabled':'')}${button('relinquish-open',t('สละสิทธิ์ในสมุด'),'dn-pencil-link dn-danger')}</div>`:''}${w.eyes?'<p class="dn-red-ink">'+esc(eyeSourceLabel(eyeAbility(w).source,uiLanguage()))+(eyeAbility(w).source==='deal'?' · '+Math.round(w.lifespanFraction*100)+'%':'')+'</p>':''}${fragmentsMarkup(w,b,rawLabel,uiLanguage())}${fragmentConfirmation()}${confirmation==='lend'?html`<div class="dn-note-contract"><h3>ผู้ถือเปลี่ยน แต่สิทธิ์ไม่เปลี่ยน</h3><p>คนที่ยืมสามารถเขียนและมองเห็นยมทูตได้เมื่อสัมผัสสมุด ความทรงจำของคุณยังอยู่</p><div class="dn-lend-list">${actorList()}</div>${button('lend',t('ส่งให้ยืม'),'dn-ink-action',actionTarget?'':'disabled')}</div>`:confirmation==='drop'?html`<div class="dn-note-contract"><h3>วางสมุดไว้ในฉากนี้</h3><p>คุณยังเป็นเจ้าของสิทธิ์และไม่สูญเสียความทรงจำ คนอื่นอาจหยิบสมุดไปได้</p>${button('drop',t('วางสมุดไว้'),'dn-ink-action')}</div>`:confirmation==='relinquish'?html`<div class="dn-note-contract"><h3>ลายเซ็นการสละสิทธิ์</h3><p>หากเป็นสมุดเล่มสุดท้ายของคุณ ความทรงจำเรื่องสมุดและดวงตาจากข้อตกลงจะหายไป ดวงตาที่มีโดยไม่แลกยังอยู่ ผู้ยืมที่ถืออยู่จะรับสิทธิ์แทน หากไม่มีผู้ถือ สมุดจะรอเจ้าของคนใหม่</p><label class="dn-ink-check"><input name="consent" type="checkbox">ฉันเข้าใจและยอมสละสิทธิ์</label>${button('relinquish',t('สละสิทธิ์'),'dn-ink-action dn-danger','disabled')}</div>`:''}`;}
 function fragmentConfirmation(){if(!['fragment-transfer','fragment-destroy'].includes(confirmation))return '';return `<div class="dn-note-contract"><h3>${confirmation==='fragment-transfer'?t('ส่งเศษกระดาษให้ใคร'):t('ทำลายเศษกระดาษนี้?')}</h3><p>${t('สิทธิ์ในสมุดและผลที่เกิดแล้วจะไม่เปลี่ยน')}</p>${confirmation==='fragment-transfer'?`<div class="dn-lend-list">${actorList()}</div>`:''}${button(confirmation,t(confirmation==='fragment-transfer'?'ส่งให้':'ยืนยันทำลาย'),'dn-pencil-link',confirmation==='fragment-transfer'&&!actionTarget?'disabled':'')}${button('fragment-cancel',t('ยกเลิก'),'dn-pencil-link')}</div>`;}
 function fragmentRightsPage(b){return `<div class="dn-paper-heading"><span>TORN PAPER</span><span>${t('เศษกระดาษ')}</span></div><h2 class="dn-hand-heading">${t('กระดาษหนึ่งชิ้น')}</h2><dl class="dn-ownership"><div><dt>${t('มาจากสมุด')}</dt><dd>${esc(b.parentBookId)}</dd></div><div><dt>${t('ผู้ถือสมุดในตอนนี้')}</dt><dd>${b.holderKnownToPlayer===false?t('ยังไม่ทราบ'):esc(label(b.holderId))}</dd></div></dl>${fragmentsMarkup(world(),b,rawLabel,uiLanguage())}${fragmentConfirmation()}<p class="dn-margin-note">${t('เศษกระดาษไม่ให้สิทธิ์เจ้าของหรือสิทธิ์แลกดวงตา')}</p>`;}
 function dealPage(){return html`<div class="dn-paper-heading"><span>死神 / THE EYE DEAL</span><span>ข้อตกลง</span></div><div class="dn-deal-eye">${fa('eye')}</div><h2 class="dn-hand-heading">ดวงตาของยมทูต</h2><p class="dn-deal-offer">ชื่อจริงของมนุษย์ที่เห็นใบหน้า<br>แลกกับครึ่งหนึ่งของอายุขัยที่เหลืออยู่</p><div class="dn-rule-stroke"></div><p>เห็นชื่อจริงข้างชื่อที่รู้จัก พร้อมอายุขัยเดิมเมื่อมีข้อมูล มองเห็นคมชัดขึ้น แต่ไม่อ่านใจหรือรู้สิ่งที่ยังไม่เห็น</p><p>อ่านอายุขัยตนเองและเจ้าของ Death Note คนอื่นไม่ได้</p><p>ใช้ได้เมื่อคุณเป็นเจ้าของสิทธิ์ในสมุด และทำข้อตกลงกับยมทูตที่ผูกกับสมุดแล้ว ชื่อปลอมจะไม่บดบังชื่อที่ดวงตาเห็น</p><p>สละสิทธิ์ในสมุดเล่มสุดท้าย ดวงตาจะหายไป แต่อายุขัยที่จ่ายแล้วจะไม่คืนกลับ การทำข้อตกลงครั้งต่อไปหักครึ่งจากส่วนที่เหลืออีกครั้ง</p><label class="dn-ink-check"><input name="consent" type="checkbox">ยอมรับข้อแลกเปลี่ยนนี้ในเนื้อเรื่อง</label><div class="dn-paper-sign">${button('eye-deal',t('ลงนามข้อตกลง'),'dn-ink-action dn-danger','disabled')}${button('rights',t('ไม่ทำข้อตกลง'),'dn-pencil-link')}</div>`;}
 function pages(){return page==='casebook'?casebookMarkup(world(),rawLabel,uiLanguage()):page==='help'?deathNoteHelp(uiLanguage()).replace('<details ','<details open '):page==='records'?recordsPage():page==='rights'?rightsPage():page==='deal'?dealPage():page==='review'?reviewPage():page==='forge'?forgePage():writePage();}
