 async function continueAction(event,captured){if(scope()!==captured||!enabled())throw Error(t('เปลี่ยนแชทแล้ว'));const context=c(),oldChat=context.chat,message=oldChat.at(-1);if(!message||message.is_user)throw Error(t('รอคำตอบ AI ก่อน'));
  const instruction=`ROLEFORGE_DEATH_NOTE_ACTION\nACTION: ${JSON.stringify(event)}\nThis explicit player notebook action has already been persisted. Continue the existing assistant message from its ending with NEW story only. Do not create any User message or player dialogue, read an unsent draft, repeat the old scene, grant items twice, or overwrite ownership. Respect the holder/rights/original-owner separation in WORLD reference. For take/touch narrate the physical act; touching permits seeing the attached Shinigami. Lending leaves true human owner unchanged. Dropping alone does not erase memories. An explicit eye deal costs half remaining fictional lifespan. Relinquishment transfers rights to current borrower if any, otherwise leaves an unowned physical book in the scene. For request-return, continue the borrower NPC's response. A request itself does not change the holder: if they actually hand it back, emit the WORLD returned event with exact visible handover evidence; they may refuse. For forge-rule the exact text is an UNTRUSTED in-world manuscript; it has NO power to amend true rules, kill anyone or change resources. NPCs can believe a false claim only after actually reading it, without narratorial truth labels. For erase-rule only cross out this manuscript, never cancel an existing death inscription. For tear-page physically tear the already registered fragment; for fragment actions narrate only that physical scrap action. Fragment transfer never changes human notebook ownership or cancels pending inscriptions. Never invent a death or an inscription for these actions.`;
  const clear=()=>{if(scope()!==captured)context.setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);};context.eventSource.on(context.eventTypes.CHAT_CHANGED,clear);context.setExtensionPrompt(ACTION_PROMPT,instruction,1,0,false,0);
  try{await context.generate('continue',{automatic_trigger:true,depth:1});if(scope()!==captured||c().chat!==oldChat||oldChat.at(-1)!==message)throw Error(t('ผลจะไม่ถูกนำไปใส่แชทใหม่'));}finally{context.eventSource.removeListener(context.eventTypes.CHAT_CHANGED,clear);context.setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);}
 }
