  if(a==='paper-clear-open'){clearPaperConfirm=true;render();renderDock();return;}
  if(a==='paper-keep'){clearPaperConfirm=false;render();renderDock();return;}
  if(a==='paper-clear'){working=true;render();renderDock();paperState=blankPaper();paperDirty=true;clearPaperConfirm=false;try{await savePaper();}catch(error){notice=t(error.message);}working=false;render();renderDock();return;}
  if(a==='paper-next'||a==='paper-prev'){working=true;render();renderDock();try{await savePaper();paperState=a==='paper-next'?nextPaper(paperState):{...paperState,active:Math.max(0,paperState.active-1)};paperDirty=true;await savePaper();}catch(error){notice=t(error.message);}working=false;render();renderDock();return;}
  if(a==='erase-rule'){eraseRuleId=act.dataset.ruleId||'';await action('erase-rule');return;}
  if(a==='forge-open'){if(access()&&!currentBook()?.parentBookId)changePage('forge');return;}
  if(a.startsWith('rule-')){const spread=ruleSpread(world(),currentBook()?.id,ruleIndex,innerWidth,uiLanguage());ruleIndex=a==='rule-first'?0:a==='rule-last'?Math.floor((spread.pages.length-1)/spread.step)*spread.step:Math.max(0,Math.min(spread.pages.length-1,spread.start+(a==='rule-prev'?-spread.step:spread.step)));changePage('rules');return;}
